(()=>{"use strict";const e=async e=>({id:e,name:"测试用户",email:"test@example.com",createdAt:new Date}),t=e=>`${e.getFullYear()}-${String(e.getMonth()+1).padStart(2,"0")}-${String(e.getDate()).padStart(2,"0")}`;class n{text;onClick;constructor(e){this.text=e.text,this.onClick=e.onClick}}new n({text:"用户",onClick:()=>{console.log("按钮点击")}}),console.log("组件加载成功"),e(1).then(e=>{console.log(`获取到用户: ${e.name}`),console.log(`格式化日期: ${t(new Date)}`)}),document.addEventListener("DOMContentLoaded",()=>{const o=document.getElementById("app");if(o){const c=new n({text:"获取用户信息",onClick:async()=>{console.log("按钮被点击");try{const n=await e(1);console.log(`获取到用户: ${n.name}`);const c=document.createElement("div");c.innerHTML=`\n                        <h3>用户信息:</h3>\n                        <p>姓名: ${n.name}</p>\n                        <p>ID: ${n.id}</p>\n                        <p>邮箱: ${n.email}</p>\n                        <p>当前时间: ${t(new Date)}</p>\n                    `,o.appendChild(c)}catch(e){console.error("获取用户信息失败:",e);const t=document.createElement("div");t.style.color="red",t.textContent="获取用户信息失败",o.appendChild(t)}}}),l=document.createElement("button");l.textContent=c.text,l.onclick=c.onClick,l.className="button",o.appendChild(l);const a=document.createElement("div");a.innerHTML="<p>点击上面的按钮来获取用户信息</p>",o.appendChild(a)}})})();